import{_ as t,o as i,c as s,a2 as n}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"为什么需要 RAG?","description":"在动手写第一行 RAG 代码之前,先想清楚:模型为什么答不对你的业务问题?","frontmatter":{},"headers":[],"relativePath":"agent/rag/0-why-rag.md","filePath":"agent/rag/0-why-rag.md","lastUpdated":1793203221000}'),l={name:"agent/rag/0-why-rag.md"};function e(r,a,o,h,p,d){return i(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="为什么需要-rag" tabindex="-1">为什么需要 RAG? <a class="header-anchor" href="#为什么需要-rag" aria-label="Permalink to &quot;为什么需要 RAG?&quot;">​</a></h1><blockquote><p>在动手写第一行 RAG 代码之前,先想清楚:模型为什么答不对你的业务问题?</p></blockquote><h2 id="一、模型的三类-不知道" tabindex="-1">一、模型的三类&quot;不知道&quot; <a class="header-anchor" href="#一、模型的三类-不知道" aria-label="Permalink to &quot;一、模型的三类&quot;不知道&quot;&quot;">​</a></h2><p>大模型是一个<strong>通用知识快照</strong>,它的知识有三个边界:</p><table tabindex="0"><thead><tr><th>不知道</th><th>典型场景</th><th>举例</th></tr></thead><tbody><tr><td><strong>私有知识</strong></td><td>你的业务数据它训练时没见过</td><td>公司内部的报销制度、你的客户订单、商品库存</td></tr><tr><td><strong>时效知识</strong></td><td>训练截止之后的新东西</td><td>昨天刚发布的 Next.js 15 特性、今天的汇率</td></tr><tr><td><strong>可溯源要求</strong></td><td>答案必须能指到原文出处</td><td>法务/客服场景,不能只给结论</td></tr></tbody></table><p>这三类问题,对应三种解法。</p><h2 id="二、三条路-为什么选了-rag" tabindex="-1">二、三条路,为什么选了 RAG <a class="header-anchor" href="#二、三条路-为什么选了-rag" aria-label="Permalink to &quot;二、三条路,为什么选了 RAG&quot;">​</a></h2><h3 id="路线-a-继续微调-fine-tuning" tabindex="-1">路线 A:继续微调(Fine-tuning) <a class="header-anchor" href="#路线-a-继续微调-fine-tuning" aria-label="Permalink to &quot;路线 A:继续微调(Fine-tuning)&quot;">​</a></h3><p>让模型&quot;记住&quot;你的知识。</p><ul><li>✅ 改变的是<strong>模型的风格和格式偏好</strong>(比如让它固定输出某种 JSON)</li><li>❌ 改变不了<strong>具体事实</strong>。用 1 万条制度文档微调一个模型,不如把这 1 万条文档放进向量库</li><li>❌ 成本高:每次知识更新都要重新训练</li></ul><h3 id="路线-b-把资料塞进-prompt" tabindex="-1">路线 B:把资料塞进 Prompt <a class="header-anchor" href="#路线-b-把资料塞进-prompt" aria-label="Permalink to &quot;路线 B:把资料塞进 Prompt&quot;">​</a></h3><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">prompt </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;请基于以下资料回答问题:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n{</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">全部文档内容</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">问题:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">question</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><ul><li>✅ 实现最简单,几行代码</li><li>❌ 上下文窗口有限,文档一多就塞不下</li><li>❌ 每次请求都把全量文档传一遍,token 成本随知识库规模线性增长</li><li>❌ 上下文里塞 100 份文档,模型很容易&quot;大海捞针&quot;失败 —— <strong>中间信息丢失</strong>是长上下文最典型的失效模式</li></ul><h3 id="路线-c-rag-检索增强生成" tabindex="-1">路线 C:RAG(检索增强生成) <a class="header-anchor" href="#路线-c-rag-检索增强生成" aria-label="Permalink to &quot;路线 C:RAG(检索增强生成)&quot;">​</a></h3><p>先<strong>检索</strong>出最相关的几段,再让模型基于这几段回答。</p><ul><li>✅ 知识更新只需重建索引,不用重训模型</li><li>✅ 只传 Top-K 相关片段,token 成本可控</li><li>✅ 天然支持溯源:把检索到的片段带引用返回</li><li>✅ 效果可观测:检索命中了什么、召回率多少,都能量化</li></ul><h2 id="三、rag-的代价-先说清楚" tabindex="-1">三、RAG 的代价(先说清楚) <a class="header-anchor" href="#三、rag-的代价-先说清楚" aria-label="Permalink to &quot;三、RAG 的代价(先说清楚)&quot;">​</a></h2><p>RAG 不是银弹,它把&quot;模型不知道&quot;换成了&quot;检索不准&quot;:</p><ul><li><strong>切分(chunking)策略</strong>直接决定召回质量</li><li><strong>Embedding 模型</strong>选不对,语义检索就废了</li><li><strong>向量库</strong>选型影响延迟和成本</li><li>**重排序(rerank)**往往比换更大模型更有效</li></ul><p>这四件事,正好对应本目录的 4 篇:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0-why-rag (本页)        为什么需要</span></span>
<span class="line"><span>0-hello-world           20 行跑通</span></span>
<span class="line"><span>1-intro                 整体流程与 5 个核心步骤</span></span>
<span class="line"><span>2-embedding             检索准不准,一半取决于 Embedding</span></span>
<span class="line"><span>3-vector-store          存哪儿</span></span>
<span class="line"><span>4-retrieval             怎么检回来(改写/HyDE/重排/混合检索)</span></span>
<span class="line"><span>5-real-rag              完整项目</span></span></code></pre></div><h2 id="四、什么时候不该用-rag" tabindex="-1">四、什么时候<strong>不</strong>该用 RAG <a class="header-anchor" href="#四、什么时候不该用-rag" aria-label="Permalink to &quot;四、什么时候**不**该用 RAG&quot;">​</a></h2><ul><li>文档极少(几条 FAQ)→ 直接塞 prompt 更简单</li><li>问题不需要引用原文 → 微调风格 or 直接调模型</li><li>强结构化查询(精确数值、聚合统计)→ SQL 比 RAG 靠谱</li><li>实时性要求极高且数据变动频繁 → 慎用 RAG,索引重建跟不上</li></ul><h2 id="🎯-面试常考" tabindex="-1">🎯 面试常考 <a class="header-anchor" href="#🎯-面试常考" aria-label="Permalink to &quot;🎯 面试常考&quot;">​</a></h2><p><strong>Q1:为什么不用微调而要用 RAG?</strong> 微调改变的是模型的<strong>行为</strong>,RAG 改变的是模型的<strong>输入</strong>。要注入具体事实,应该改输入;要固定输出格式/语气/风格,才考虑微调。微调的知识更新成本也远高于重建索引。</p><p><strong>Q2:RAG 和长上下文(RAG 替代方案)怎么选?</strong> 文档量在上下文窗口内(如 20 万 token)且查询不聚焦时,直接塞长上下文更简单;文档量大、查询聚焦、需要溯源、需要频繁更新时,RAG 更优。实践中常混用:先用检索缩小范围,再长上下文精读。</p><p><strong>Q3:RAG 的效果怎么评估?</strong> 分两段:检索侧看<strong>召回率</strong>(正确片段有没有被检回来,常用 Recall@k / MRR);生成侧看<strong>忠实度</strong>(回答是否只依赖检索到的内容)。检索没召回,生成再好也没用,所以先查检索。</p><h2 id="📚-延伸阅读" tabindex="-1">📚 延伸阅读 <a class="header-anchor" href="#📚-延伸阅读" aria-label="Permalink to &quot;📚 延伸阅读&quot;">​</a></h2><ul><li><a href="/agent/rag/1-intro">RAG 入门(整体流程)</a></li><li><a href="/agent/rag/2-embedding">Embedding 模型选型</a></li><li><a href="/agent/rag/4-retrieval">检索策略与优化</a></li><li><a href="/img/%E9%9D%A2%E8%AF%95/%E5%9C%BA%E6%99%AF%E9%A2%98/q61-rag-pipeline.svg">RAG 应用流水线(SVG)</a></li></ul><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>模型的&quot;不知道&quot;分私有知识、时效知识、可溯源三类,RAG 主要解决前两类并顺带解决第三类。</li><li>三条路的取舍:微调改行为、RAG 改输入、塞 prompt 是最朴素的方案。</li><li>RAG 的真实成本在检索侧 —— 切分、Embedding、向量库、重排,这四件事决定效果上限。</li><li>文档少、查询不聚焦、需要精确统计的场景,RAG 未必是更好的选择。</li></ul>`,31)])])}const c=t(l,[["render",e]]);export{u as __pageData,c as default};
